          "heightUnits": "Height units",
          "heightCm": "Height (cm)",
          "heightFt": "Height (ft)",
          "heightIn": "Height (in)",
          "tapeUnits": "Tape units",
          "neck": "Neck",
          "waist": "Waist",
          "hip": "Hip",
